import{_ as t,c as a,o as s,ag as o}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"REST API","description":"Server API endpoints","frontmatter":{"title":"REST API","description":"Server API endpoints"},"headers":[],"relativePath":"engine/rest_api.md","filePath":"engine/rest_api.md","lastUpdated":1793057853000}'),d={name:"engine/rest_api.md"};function i(n,e,r,c,h,p){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h1><p>OIE exposes a REST API, the one the desktop Administrator, the Web Administrator, and the CLI use. The engine serves its own endpoint reference; see <a href="#swagger-openapi">Swagger / OpenAPI</a>.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;:8443/api</span></span></code></pre></div><p>The port comes from <code>https.port</code> and the prefix before <code>/api</code> from <code>http.contextpath</code>, both in <code>mirth.properties</code>; the defaults are shown. The API is served over HTTPS, and every request must be authenticated except <code>/api/server/version</code>, <code>/api/server/status</code>, and the API documentation (see <a href="#api-documentation">API documentation</a>). Requests must also carry an <code>X-Requested-With</code> header for CSRF protection, the Swagger UI page itself excepted; any non-blank value is accepted (<code>server.api.require-requested-with</code>, default <code>true</code>).</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><h3 id="session-based" tabindex="-1">Session-based <a class="header-anchor" href="#session-based" aria-label="Permalink to &quot;Session-based&quot;">​</a></h3><ol><li>POST a form body (<code>application/x-www-form-urlencoded</code>) with <code>username</code> and <code>password</code> fields to <code>/api/users/_login</code></li><li>Send the <code>JSESSIONID</code> cookie from the response on subsequent requests</li></ol><h3 id="http-headers" tabindex="-1">HTTP headers <a class="header-anchor" href="#http-headers" aria-label="Permalink to &quot;HTTP headers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-Requested-With</code></td><td>Yes (by default)</td><td>CSRF protection header (any value)</td></tr><tr><td><code>Authorization</code></td><td>If no session</td><td>HTTP Basic (<code>username:password</code>)</td></tr><tr><td><code>Content-Type</code></td><td>For POST/PUT</td><td><code>application/xml</code> or <code>application/json</code> for the object endpoints. Login takes <code>application/x-www-form-urlencoded</code>, posting a message to a channel takes <code>text/plain</code>, and installing an extension takes <code>multipart/form-data</code></td></tr><tr><td><code>Accept</code></td><td>Optional</td><td><code>application/xml</code> (the default) or <code>application/json</code></td></tr></tbody></table><h3 id="example-curl" tabindex="-1">Example (curl) <a class="header-anchor" href="#example-curl" aria-label="Permalink to &quot;Example (curl)&quot;">​</a></h3><p>Lists every channel the account in <code>-u</code> can see, with HTTP Basic authentication, and returns the channel definitions as JSON. Any non-blank <code>X-Requested-With</code> value passes the CSRF filter, and <code>-k</code> skips verification of the certificate the server generates for itself. Without the <code>Accept</code> header the response is XML.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Requested-With: OIE&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;username&gt;:&lt;password&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://localhost:8443/api/channels</span></span></code></pre></div><h2 id="api-documentation" tabindex="-1">API documentation <a class="header-anchor" href="#api-documentation" aria-label="Permalink to &quot;API documentation&quot;">​</a></h2><h3 id="swagger-openapi" tabindex="-1">Swagger / OpenAPI <a class="header-anchor" href="#swagger-openapi" aria-label="Permalink to &quot;Swagger / OpenAPI&quot;">​</a></h3><p>The API base URL, opened in a browser, serves the Swagger UI:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;:8443/api</span></span></code></pre></div><p>The OpenAPI spec is available in JSON and YAML formats at <code>/api/openapi.json</code> and <code>/api/openapi.yaml</code>. Both live inside the API context, so they need the <code>X-Requested-With</code> header but no login:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Requested-With: OIE&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://localhost:8443/api/openapi.json</span></span></code></pre></div><p>The Swagger UI includes parameter descriptions, request/response schemas, and example payloads.</p><h3 id="user-api-javadocs" tabindex="-1">User API Javadocs <a class="header-anchor" href="#user-api-javadocs" aria-label="Permalink to &quot;User API Javadocs&quot;">​</a></h3><p>Generated Javadocs for the User API (classes available in channel scripts) are served at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;:8443/javadocs/user-api/</span></span></code></pre></div><p><code>/javadocs/</code> on its own is a directory listing of the installation&#39;s <code>docs/javadocs</code> folder, with <code>user-api/</code> as its entry.</p><h2 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h2><p>The API returns these HTTP status codes:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200</code></td><td>Success</td></tr><tr><td><code>204</code></td><td>Success with no content; also returned for a channel or message ID that does not exist</td></tr><tr><td><code>400</code></td><td>The <code>X-Requested-With</code> header is missing or blank</td></tr><tr><td><code>401</code></td><td>Unauthorized (no session and no valid credentials)</td></tr><tr><td><code>403</code></td><td>Forbidden. Only an authorization extension, such as Role Based Access Control, returns it; the stock engine lets every user make every call</td></tr><tr><td><code>404</code></td><td>Not found; also returned for a path or query value of the wrong type, such as a non-numeric message ID</td></tr><tr><td><code>405</code></td><td>The path does not accept that HTTP method</td></tr><tr><td><code>406</code></td><td>The <code>Accept</code> header names a type the call cannot produce</td></tr><tr><td><code>415</code></td><td>The request body&#39;s <code>Content-Type</code> is not one the call accepts</td></tr><tr><td><code>500</code></td><td>Internal server error; also returned for a request body that cannot be parsed</td></tr><tr><td><code>503</code></td><td>Server still starting or otherwise unavailable</td></tr></tbody></table><p>A <code>500</code> comes back as an HTML error page reading <code>Request failed.</code> when the request sends no <code>Accept</code> header, and as a JSON error object when it sends <code>Accept: application/json</code>. A <code>400</code> or <code>404</code> can come back with an empty body.</p>`,28)]))}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
